/* Start here entry for surface-tension (demos/lib/starthere/surface-tension.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"Water climbs up a thin glass tube. In a tube half as wide, does it climb twice as high, four times as high, or the same?","q_es":"El agua sube por un tubo delgado de vidrio. En un tubo de la mitad de ancho, ¿sube el doble, cuatro veces más o lo mismo?","setup":"","do":"Three glass tubes of radius r, 2r and 4r stand in water. Press <b>Play</b>, wait for the water to stop climbing, then read <b>Height now</b> for each tube.","do_es":"Tres tubos de vidrio de radio r, 2r y 4r están parados en agua. Presiona <b>Iniciar</b>, espera a que el agua deje de subir y luego lee <b>Altura ahora</b> en cada tubo.","see":"The water climbs 5.94 cm in the 250 μm tube, 2.97 cm in the 500 μm tube and 1.48 cm in the 1.00 mm tube: half the radius, twice the height, h = 2γ cos θ/(ρgr). The surface pulls up along the rim, which grows as r, while the column's weight grows as r².","see_es":"El agua sube 5.94 cm en el tubo de 250 μm, 2.97 cm en el de 500 μm y 1.48 cm en el de 1.00 mm: la mitad del radio, el doble de altura, h = 2γ cos θ/(ρgr). La superficie jala hacia arriba a lo largo del borde, que crece como r, mientras que el peso de la columna crece como r².","explore":[{"setup":"set=selSpeed~0.25!selLiqT~mercury!selMat~glass!sR~-0.6!chkTheta~0!labBlind~0!g%3Apresets~mercury","do":"<b>Mercury sinks in glass</b>. Predict first: does mercury climb too? Press <b>Play</b> and read <b>Height now, tube r</b>.","do_es":"<b>El mercurio baja en el vidrio</b>. Predice primero: ¿el mercurio también sube? Presiona <b>Iniciar</b> y lee <b>Altura ahora, tubo r</b>.","see":"It ends 2.14 cm below the level in the dish. Mercury meets glass at 140°, so cos θ is negative and the surface pulls the column down instead of up.","see_es":"Termina 2.14 cm por debajo del nivel del plato. El mercurio toca el vidrio a 140°, así que cos θ es negativo y la superficie jala la columna hacia abajo en vez de hacia arriba."},{"setup":"set=selSpeed~0.1!selLiqB~soap!sRd~-3.7!sB1~1.5!sB2~4!labBlind~0!g%3AsceneSeg~drops!g%3Apresets~bubbles","do":"<b>Two bubbles: which one wins?</b> A 1.50 cm and a 4.00 cm soap bubble sit on the ends of a pipe. Predict which way the air will flow, then press <b>Play</b> and read <b>Left bubble R</b> and <b>Right bubble R</b>.","do_es":"<b>Dos burbujas: ¿cuál gana?</b> Una burbuja de jabón de 1.50 cm y otra de 4.00 cm están en los extremos de un tubo. Predice hacia dónde fluirá el aire, luego presiona <b>Iniciar</b> y lee <b>R de la burbuja izquierda</b> y <b>R de la burbuja derecha</b>.","see":"The small bubble empties into the big one: the pressure 4γ/R is 9.87 Pa inside the small one and only 3.70 Pa inside the big one. It stops when the small one has shrunk to a flat dome with the same radius as the big one, 4.07 cm.","see_es":"La burbuja chica se vacía en la grande: la presión 4γ/R es 9.87 Pa dentro de la chica y solo 3.70 Pa dentro de la grande. Se detiene cuando la chica se ha encogido a un domo plano con el mismo radio que la grande, 4.07 cm."},{"setup":"set=selSpeed~1!selLiqS~water20!selMetal~steel!sD~1!sL~4!labBlind~0!g%3AsceneSeg~surf!g%3Apresets~needle","do":"<b>A steel needle rests on water</b>, then <b>A thicker needle sinks</b>. Press <b>Play</b> for each and compare <b>Weight w</b> with <b>Most the surface holds, 2γL</b>.","do_es":"<b>Una aguja de acero descansa sobre el agua</b>, luego <b>Una aguja más gruesa se hunde</b>. Presiona <b>Iniciar</b> en cada una y compara <b>Peso w</b> con <b>Lo más que sostiene la superficie, 2γL</b>.","see":"The 1.0 mm needle weighs 2.40 mN and the surface can hold 5.82 mN, so it rests. The 2.0 mm needle weighs four times as much, 9.62 mN, against the same 5.82 mN, so it sinks. Steel is 7.8 times as dense as water: the stretched surface holds the needle up, not floating like a boat.","see_es":"La aguja de 1.0 mm pesa 2.40 mN y la superficie puede sostener 5.82 mN, así que descansa. La aguja de 2.0 mm pesa cuatro veces más, 9.62 mN, contra los mismos 5.82 mN, así que se hunde. El acero es 7.8 veces más denso que el agua: la superficie estirada sostiene la aguja, no flota como un barco."}]});
